def semver_sort(versions):
    def parse(v):
        main = v
        build = None
        if '+' in main:
            main, build = main.split('+', 1)
        prerelease = None
        if '-' in main:
            main, prerelease = main.split('-', 1)
        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        if prerelease is None:
            has_pre = 0  # no prerelease -> higher precedence -> sorts after
            pre_ids = []
        else:
            has_pre = -1  # has prerelease -> lower precedence -> sorts before
            ids = prerelease.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))
        return (major, minor, patch, has_pre, pre_ids)

    return sorted(versions, key=parse)

